using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
namespace LittleNotebook {
 public sealed class ExtraPuzzle {
  public static readonly string[] Keys={"lights","queens","crates","pegs","untangle","pour","code","domino","glide","flood"};
  public readonly string Kind;public readonly int Level;public int LastFrom=-1,LastTo=-1,LastColour=-1,PreviousPlayer=-1;public int W,H,Selected=-1,Moves,Player,Colours,Limit,Focus,Last=-1;public bool Won,Over;public double Feedback;public string Message="";
  public int[] Cells,Goal,Given;public List<int[]> Edges=new List<int[]>(),Guesses=new List<int[]>(),Scores=new List<int[]>();public List<Point> Points=new List<Point>(),Original=new List<Point>();public List<List<int>> Tubes=new List<List<int>>();public List<int> Solution=new List<int>();
  readonly Stack<State> undo=new Stack<State>();
  sealed class State {public int[] Cells;public int Selected,Player,Moves;public List<List<int>> Tubes;public List<Point> Points;public int Guesses,Edges;}
  void Save(){undo.Push(new State{Cells=(int[])Cells.Clone(),Selected=Selected,Player=Player,Moves=Moves,Tubes=Tubes.Select(t=>t.ToList()).ToList(),Points=Points.ToList(),Guesses=Guesses.Count,Edges=Edges.Count});}
  public bool Undo(){if(undo.Count==0)return false;var s=undo.Pop();Cells=s.Cells;Selected=s.Selected;Player=s.Player;Moves=s.Moves;Tubes=s.Tubes;Points=s.Points;while(Guesses.Count>s.Guesses){Guesses.RemoveAt(Guesses.Count-1);Scores.RemoveAt(Scores.Count-1);}if(Kind=="domino")while(Edges.Count>s.Edges)Edges.RemoveAt(Edges.Count-1);Won=Over=false;LastFrom=LastTo=PreviousPlayer=-1;Message="";Feedback=.2;return true;}
  public ExtraPuzzle(string kind,int level,int seed){Kind=kind;Level=level;var r=new Random(seed);W=H=5;Cells=new int[25];Goal=new int[25];Given=new int[25];
   if(kind=="lights"){W=H=Math.Min(8,3+(level-1)/4);Cells=new int[W*H];Goal=new int[Cells.Length];foreach(int c in Enumerable.Range(0,Cells.Length).OrderBy(x=>r.Next()).Take(Math.Min(Cells.Length,3+level*2))){Toggle(c);Solution.Add(c);}if(Cells.All(x=>x==0)){Toggle(0);Solution.Add(0);}}
   if(kind=="queens"){W=H=Math.Min(11,4+(level-1)/3);Cells=new int[W*H];Goal=new int[Cells.Length];int[] columns=new int[W];Func<int,bool> solve=null;solve=row=>{if(row==W)return true;foreach(int col in Enumerable.Range(0,W).OrderBy(x=>r.Next())){if(Enumerable.Range(0,row).Any(y=>columns[y]==col||Math.Abs(columns[y]-col)==row-y))continue;columns[row]=col;if(solve(row+1))return true;}return false;};solve(0);for(int y=0;y<H;y++){Goal[y*W+columns[y]]=1;Solution.Add(y*W+columns[y]);}Given=new int[Cells.Length];foreach(int c in Solution.OrderBy(x=>r.Next()).Take(level<4?1:0))Given[c]=Cells[c]=1;}
   if(kind=="crates")MakeCrates(r);
   if(kind=="pegs")MakePegs(r);
   if(kind=="untangle"){W=Math.Min(6,3+(level-1)/8);H=Math.Min(5,2+(level-1)/10);Cells=new int[W*H];for(int y=0;y<H;y++)for(int x=0;x<W;x++){int i=y*W+x;Original.Add(new Point(100+x*480.0/Math.Max(1,W-1),65+y*260.0/Math.Max(1,H-1)));if(x<W-1)Edges.Add(new[]{i,i+1});if(y<H-1)Edges.Add(new[]{i,i+W});if(x<W-1&&y<H-1&&r.NextDouble()<.35)Edges.Add(new[]{i,i+W+1});}Points=Original.OrderBy(x=>r.Next()).ToList();for(int retry=0;Crossings()==0&&retry<100;retry++)Points=Original.OrderBy(x=>r.Next()).ToList();}
   if(kind=="pour")MakePour(r);
   if(kind=="code"){Colours=Math.Min(8,5+(level-1)/6);W=Math.Min(6,4+(level-1)/12);H=1;Cells=Enumerable.Repeat(-1,W).ToArray();Goal=Enumerable.Range(0,W).Select(x=>r.Next(Colours)).ToArray();Limit=Math.Max(8,12-(level-1)/10);}
   if(kind=="domino")MakeDomino(r);
   if(kind=="glide")MakeGlide(r);
   if(kind=="flood"){W=H=Math.Min(14,6+(level-1)/3);Colours=Math.Min(6,4+(level-1)/10);Cells=Enumerable.Range(0,W*H).Select(x=>r.Next(Colours)).ToArray();Goal=(int[])Cells.Clone();while(!Cells.All(x=>x==Cells[0])){int choice=Enumerable.Range(0,Colours).Where(c=>c!=Cells[0]).OrderByDescending(c=>FloodSize(c)).First();Flood(choice);Solution.Add(choice);}Cells=(int[])Goal.Clone();Limit=Solution.Count+Math.Max(1,5-level/4);}
   if(Given.Length!=Cells.Length)Given=new int[Cells.Length];
  }
  public bool Input(int index,bool alternate=false){if(Won||Over)return false;Feedback=.22;Last=index;Message="";
   if(Kind=="untangle")return false;
   if(Kind=="code"){if(index>=100){int colour=index-100;if(colour<Colours){Save();Cells[Focus]=colour;Focus=(Focus+1)%W;return true;}return false;}if(index==99)return Guess();if(index>=0&&index<W){Focus=index;return true;}return false;}
   if(Kind=="pour")return Pour(index);
   if(Kind=="flood"){if(index<0||index>=Colours||index==Cells[0])return false;Save();Flood(index);Moves++;Won=Cells.All(x=>x==Cells[0]);Over=!Won&&Moves>=Limit;return true;}
   if(index<0||index>=Cells.Length)return false;Focus=index;
   if(Kind=="lights"){Save();Toggle(index);Moves++;Won=Cells.All(x=>x==0);return true;}
   if(Kind=="queens"){if(Given[index]==1)return false;Save();Cells[index]=Cells[index]==1?0:1;Moves++;Won=Cells.Sum()==W&&!Enumerable.Range(0,Cells.Length).Any(Conflict);return true;}
   if(Kind=="crates"){int d=Enumerable.Range(0,4).FirstOrDefault(x=>MiniGrid.Next(Player,x,W,H)==index,-1);return d>=0&&Move(d);}
   if(Kind=="glide"){int dx=index%W-Player%W,dy=index/W-Player/W;if(dx==0&&dy!=0)return Move(dy>0?2:0);if(dy==0&&dx!=0)return Move(dx>0?1:3);return false;}
   if(Kind=="pegs"){if(Cells[index]==1){Selected=index;return true;}if(Selected>=0){int a=Selected;int dx=index%W-a%W,dy=index/W-a/W;if((Math.Abs(dx)==2&&dy==0||Math.Abs(dy)==2&&dx==0)&&Cells[(a+index)/2]==1){Save();Cells[a]=Cells[(a+index)/2]=0;Cells[index]=1;Selected=-1;Moves++;Won=Cells.Sum()==1;return true;}}Message="blocked";return false;}
   if(Kind=="domino"){if(Cells[index]<0)return false;if(Selected<0){Selected=index;return true;}int a=Selected;if(a==index){Selected=-1;return true;}if(Math.Abs(a%W-index%W)+Math.Abs(a/W-index/W)==1){int key=Math.Min(Cells[a],Cells[index])*10+Math.Max(Cells[a],Cells[index]);if(Solution.Any(action=>{int x=Cells[action/1000],y=Cells[action%1000];x=x<0?-x-1:x;y=y<0?-y-1:y;return Math.Min(x,y)*10+Math.Max(x,y)==key;})&&!Edges.Any(e=>e[0]==key&&e[1]==1)){Save();Cells[a]=-Cells[a]-1;Cells[index]=-Cells[index]-1;Edges.Add(new[]{key,1,a,index});Moves++;Selected=-1;Won=Cells.All(x=>x<0);return true;}}Selected=index;Message="blocked";return false;}
   return false;
  }
  public bool Move(int direction){if(Won||Over)return false;
   if(Kind=="crates"){int next=MiniGrid.Next(Player,direction,W,H);if(next<0||Cells[next]==-1)return false;int beyond=MiniGrid.Next(next,direction,W,H);if(Cells[next]==1&&(beyond<0||Cells[beyond]!=0))return false;Save();if(Cells[next]==1){Cells[next]=0;Cells[beyond]=1;}PreviousPlayer=Player;Player=next;Last=next;Moves++;Won=Enumerable.Range(0,Cells.Length).Where(i=>Goal[i]==1).All(i=>Cells[i]==1);Feedback=.18;return true;}
   if(Kind=="glide"){int next=Player,step;while((step=MiniGrid.Next(next,direction,W,H))>=0&&Cells[step]!=-1)next=step;if(next==Player)return false;Save();PreviousPlayer=Player;Player=next;Last=next;Moves++;Won=Player==Selected;Feedback=.2;return true;}return false;
  }
  public bool Conflict(int index){if(Cells[index]!=1)return false;return Enumerable.Range(0,Cells.Length).Any(i=>i!=index&&Cells[i]==1&&(i%W==index%W||i/W==index/W||Math.Abs(i%W-index%W)==Math.Abs(i/W-index/W)));}
  void Toggle(int c){foreach(int at in new[]{c}.Concat(Enumerable.Range(0,4).Select(d=>MiniGrid.Next(c,d,W,H))).Where(i=>i>=0))Cells[at]^=1;}
  void MakeCrates(Random r){W=H=Math.Min(10,6+(Level-1)/5);int[] best=null;List<int> proof=null;int bestPlayer=0,bestScore=-1;for(int attempt=0;attempt<30;attempt++){Cells=new int[W*H];for(int i=0;i<Cells.Length;i++)if(i%W==0||i%W==W-1||i/W==0||i/W==H-1)Cells[i]=-1;else if(r.NextDouble()<.12)Cells[i]=-1;Goal=new int[Cells.Length];var free=Enumerable.Range(0,Cells.Length).Where(i=>Cells[i]==0).OrderBy(x=>r.Next()).ToArray();int crates=Math.Min(5,1+(Level+1)/3);foreach(int c in free.Take(crates))Goal[c]=Cells[c]=1;Player=free[crates];var actions=new List<int>();int pulls=0;for(int step=0;step<80+Math.Min(500,Level*12);step++){int d=r.Next(4),next=MiniGrid.Next(Player,d,W,H);if(next<0||Cells[next]!=0)continue;int behind=MiniGrid.Next(Player,MiniGrid.Opposite(d),W,H);if(behind>=0&&Cells[behind]==1&&r.NextDouble()<.8){Cells[behind]=0;Cells[Player]=1;pulls++;}Player=next;actions.Add(MiniGrid.Opposite(d));}int score=Enumerable.Range(0,Cells.Length).Count(i=>Cells[i]==1&&Goal[i]==0)*100+pulls;if(score>bestScore){bestScore=score;best=(int[])Cells.Clone();proof=actions.AsEnumerable().Reverse().ToList();bestPlayer=Player;crateGoals=(int[])Goal.Clone();}if(score>=crates*100+10)break;}Cells=best;Goal=crateGoals;Player=bestPlayer;Solution=proof;}
  int[] crateGoals;
  void MakePegs(Random r){W=H=Math.Min(9,5+(Level-1)/8);int target=Math.Min(W*H-3,4+Level);int best=0;for(int attempt=0;attempt<50;attempt++){var cells=new int[W*H];cells[r.Next(cells.Length)]=1;var proof=new List<int>();while(cells.Sum()<target){var options=new List<int[]>();for(int i=0;i<cells.Length;i++)if(cells[i]==1)for(int d=0;d<4;d++){int a=MiniGrid.Next(i,d,W,H),b=a<0?-1:MiniGrid.Next(a,d,W,H);if(b>=0&&cells[a]==0&&cells[b]==0)options.Add(new[]{i,a,b});}if(options.Count==0)break;var move=options[r.Next(options.Count)];cells[move[0]]=0;cells[move[1]]=cells[move[2]]=1;proof.Add(move[2]*1000+move[0]);}if(cells.Sum()>best){best=cells.Sum();Cells=cells;Solution=proof.AsEnumerable().Reverse().ToList();}if(best>=target)break;}Goal=new int[Cells.Length];}
  void MakePour(Random r){int count=Math.Min(9,3+(Level-1)/5);W=count+2;H=4;Colours=count;Tubes=Enumerable.Range(0,count).Select(c=>Enumerable.Repeat(c,4).ToList()).Concat(new[]{new List<int>(),new List<int>()}).ToList();for(int i=0;i<40+Math.Min(600,Level*15);i++){var choices=new List<int[]>();for(int a=0;a<W;a++)if(Tubes[a].Count>0&&(Tubes[a].Count==1||Tubes[a][Tubes[a].Count-2]==Tubes[a].Last()))for(int b=0;b<W;b++)if(a!=b&&Tubes[b].Count<4&&(Tubes[b].Count==0||Tubes[b].Last()!=Tubes[a].Last()))choices.Add(new[]{a,b});if(choices.Count==0)break;var m=choices[r.Next(choices.Count)];int c=Tubes[m[0]].Last();Tubes[m[0]].RemoveAt(Tubes[m[0]].Count-1);Tubes[m[1]].Add(c);Solution.Add(m[1]*100+m[0]);}Solution.Reverse();Cells=new int[W];Goal=new int[W];}
  bool Pour(int to){if(to<0||to>=Tubes.Count)return false;if(Selected<0){if(Tubes[to].Count==0)return false;Selected=to;return true;}int from=Selected;if(from==to){Selected=-1;return true;}if(Tubes[from].Count==0||Tubes[to].Count==4||Tubes[to].Count>0&&Tubes[to].Last()!=Tubes[from].Last()){Selected=to;Message="blocked";return false;}Save();int colour=Tubes[from].Last();LastFrom=from;LastTo=to;LastColour=colour;Tubes[from].RemoveAt(Tubes[from].Count-1);Tubes[to].Add(colour);Selected=-1;Moves++;Won=Tubes.All(t=>t.Count==0||t.Count==4&&t.All(c=>c==t[0]));return true;}
  bool Guess(){if(Cells.Any(c=>c<0))return false;Save();int exact=Enumerable.Range(0,W).Count(i=>Cells[i]==Goal[i]),all=Enumerable.Range(0,Colours).Sum(c=>Math.Min(Cells.Count(x=>x==c),Goal.Count(x=>x==c)));Guesses.Add((int[])Cells.Clone());Scores.Add(new[]{exact,all-exact});Moves++;Won=exact==W;Over=!Won&&Moves>=Limit;return true;}
  void MakeDomino(Random r){W=Level<5?4:6;H=Level<5?3:Level<15?4:6;Cells=new int[W*H];Goal=new int[Cells.Length];var tiles=new List<int[]>();for(int y=0;y<H;y++)for(int x=0;x<W;x+=2)tiles.Add(new[]{y*W+x,y*W+x+1});for(int step=0;step<100;step++){int a=r.Next(tiles.Count),b=r.Next(tiles.Count);if(a==b)continue;var four=tiles[a].Concat(tiles[b]).ToArray();if(four.Max(c=>c%W)-four.Min(c=>c%W)==1&&four.Max(c=>c/W)-four.Min(c=>c/W)==1){int top=four.Min();bool horizontal=tiles[a][0]/W==tiles[a][1]/W;tiles[a]=horizontal?new[]{top,top+W}:new[]{top,top+1};tiles[b]=horizontal?new[]{top+1,top+W+1}:new[]{top+W,top+W+1};}}var pairs=(from a in Enumerable.Range(0,6) from b in Enumerable.Range(a,6-a) select new[]{a,b}).OrderBy(x=>r.Next()).ToArray();for(int i=0;i<tiles.Count;i++){var t=tiles[i];Cells[t[0]]=pairs[i][0];Cells[t[1]]=pairs[i][1];Goal[t[0]]=Goal[t[1]]=i+1;Solution.Add(t[0]*1000+t[1]);}}
  void MakeGlide(Random r){W=H=Math.Min(13,6+(Level-1)/4);for(int attempt=0;attempt<200;attempt++){Cells=Enumerable.Range(0,W*H).Select(i=>r.NextDouble()<.19?-1:0).ToArray();Player=r.Next(Cells.Length);Cells[Player]=0;int[] dist=Enumerable.Repeat(-1,Cells.Length).ToArray(),prev=Enumerable.Repeat(-1,Cells.Length).ToArray(),dirs=new int[Cells.Length];var queue=new Queue<int>();queue.Enqueue(Player);dist[Player]=0;while(queue.Count>0){int at=queue.Dequeue();for(int d=0;d<4;d++){int next=at,step;while((step=MiniGrid.Next(next,d,W,H))>=0&&Cells[step]!=-1)next=step;if(dist[next]>=0)continue;dist[next]=dist[at]+1;prev[next]=at;dirs[next]=d;queue.Enqueue(next);}}Selected=Enumerable.Range(0,Cells.Length).OrderByDescending(i=>dist[i]).First();if(dist[Selected]<4)continue;Solution.Clear();for(int at=Selected;at!=Player;at=prev[at])Solution.Add(dirs[at]);Solution.Reverse();Goal=new int[Cells.Length];return;}throw new InvalidOperationException("Could not generate a glide route");}
  HashSet<int> Region(){var found=new HashSet<int>{0};var queue=new Queue<int>();queue.Enqueue(0);while(queue.Count>0){int at=queue.Dequeue();for(int d=0;d<4;d++){int next=MiniGrid.Next(at,d,W,H);if(next>=0&&Cells[next]==Cells[0]&&found.Add(next))queue.Enqueue(next);}}return found;}
  void Flood(int colour){foreach(int at in Region())Cells[at]=colour;}
  int FloodSize(int colour){var old=(int[])Cells.Clone();Flood(colour);int n=Region().Count;Cells=old;return n;}
  public int Crossings(){int count=0;for(int a=0;a<Edges.Count;a++)for(int b=a+1;b<Edges.Count;b++)if(EdgesCross(a,b))count++;return count;}
  static double Cross(Point a,Point b,Point c){return Vector.CrossProduct(b-a,c-a);}
  static bool OnSegment(Point a,Point b,Point c){return Math.Abs(Cross(a,b,c))<.01&&c.X>=Math.Min(a.X,b.X)-.01&&c.X<=Math.Max(a.X,b.X)+.01&&c.Y>=Math.Min(a.Y,b.Y)-.01&&c.Y<=Math.Max(a.Y,b.Y)+.01;}
  public bool EdgesCross(int a,int b){var x=Edges[a];var y=Edges[b];if(x[0]==y[0]||x[0]==y[1]||x[1]==y[0]||x[1]==y[1])return false;Point p=Points[x[0]],q=Points[x[1]],u=Points[y[0]],v=Points[y[1]];return Cross(p,q,u)*Cross(p,q,v)<0&&Cross(u,v,p)*Cross(u,v,q)<0||OnSegment(p,q,u)||OnSegment(p,q,v)||OnSegment(u,v,p)||OnSegment(u,v,q);}
  public void BeginDrag(int index){if(Kind!="untangle"||Won)return;Save();Selected=index;}
  public void Drag(Point point){if(Kind=="untangle"&&Selected>=0){Points[Selected]=new Point(Math.Max(30,Math.Min(650,point.X)),Math.Max(30,Math.Min(380,point.Y)));Feedback=.1;}}
  public void EndDrag(){if(Kind!="untangle"||Selected<0)return;Selected=-1;Moves++;Won=Crossings()==0&&!Points.Where((p,i)=>Points.Where((q,j)=>j!=i).Any(q=>(p-q).Length<22)).Any();Feedback=.3;}
 }
}
